"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["24372"],{82111(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.etapa_referenciada_por_classificacao","status":422,"titulo":"Etapa referenciada por regra de elimina\xe7\xe3o da classifica\xe7\xe3o"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.etapa_referenciada_por_classificacao","requisitos":[],"oQueAconteceu":["O processo j\xe1 tem uma configura\xe7\xe3o de classifica\xe7\xe3o definida, com uma\\nregra de elimina\xe7\xe3o de c\xf3digo `ELIMINACAO_NOTA_MINIMA_ETAPA` ou `ELIMINACAO_AUSENCIA_NA_ETAPA`, e o novo corpo do pedido de\\ndefini\xe7\xe3o de etapas omite a etapa que essa regra referencia (`etapaRef`).\\n\xc9 a mesma prote\xe7\xe3o de\\n[`etapa_referenciada_por_desempate`](/erros/uniplus.selecao.processo_seletivo.etapa_referenciada_por_desempate)\\n(INV-B6), aqui para a classifica\xe7\xe3o (INV-B4): substituir a lista de etapas\\nsem revalidar deixaria a regra de elimina\xe7\xe3o apontando para uma etapa\\nremovida.","S\xf3 \xe9 conferida quando o processo j\xe1 tem classifica\xe7\xe3o definida \u2014 antes\\ndisso, n\xe3o h\xe1 o que proteger. Roda por \xfaltimo dentre as confer\xeancias da\\nsubstitui\xe7\xe3o de etapas: depois de\\n[`ordem_etapa_duplicada`](/erros/uniplus.selecao.processo_seletivo.ordem_etapa_duplicada),\\n[`nenhuma_etapa_compoe_nota`](/erros/uniplus.selecao.processo_seletivo.nenhuma_etapa_compoe_nota)\\ne\\n[`etapa_referenciada_por_desempate`](/erros/uniplus.selecao.processo_seletivo.etapa_referenciada_por_desempate)\\nj\xe1 terem passado. N\xe3o acumula com nenhuma delas \u2014 a primeira que falhar\\ninterrompe a substitui\xe7\xe3o."],"comoResolver":["O gatilho mais comum n\xe3o \xe9 uma remo\xe7\xe3o intencional: o `PUT` de etapas\\nreconcilia a lista inteira **pelo campo `id`** de cada item \u2014 uma etapa\\nexistente reenviada sem `id` (ou com um `id` que n\xe3o bate com nenhuma\\netapa atual) n\xe3o \xe9 reconhecida como a mesma etapa, e vira uma etapa nova,\\ncom identificador novo, mesmo que os demais campos sejam id\xeanticos. Se a\\ninten\xe7\xe3o era s\xf3 editar outro campo de uma etapa que a classifica\xe7\xe3o j\xe1\\nreferencia (peso, nota m\xednima, nome), confira que o `id` dela foi ecoado no\\ncorpo do pedido \u2014 sem alter\xe1-lo, o `etapaRef` continua resolvendo, e a mudan\xe7a\\nsegue sem precisar tocar na classifica\xe7\xe3o.","Se a remo\xe7\xe3o da etapa \xe9 de fato intencional, reconfigure a classifica\xe7\xe3o\\nantes \u2014 redirecione a regra de elimina\xe7\xe3o para outra etapa, troque o\\nc\xf3digo da regra, ou remova a regra. S\xf3 ent\xe3o redefina as etapas."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);